#define IOCON_PIO_FUNC0 0x00u         /*!<@brief Selects pin function 0 */
#define IOCON_PIO_FUNC1 0x01u         /*!<@brief Selects pin function 1 */
#define IOCON_PIO_FUNC2 0x02u         /*!<@brief Selects pin function 2 */
#define IOCON_PIO_FUNC3 0x03u         /*!<@brief Selects pin function 3 */
#define IOCON_PIO_FUNC4 0x04u         /*!<@brief Selects pin function 4 */
#define IOCON_PIO_FUNC5 0x05u         /*!<@brief Selects pin function 5 */
#define IOCON_PIO_FUNC6 0x06u         /*!<@brief Selects pin function 6 */
#define IOCON_PIO_FUNC7 0x07u         /*!<@brief Selects pin function 7 */
#define IOCON_PIO_FUNC8 0x08u         /*!<@brief Selects pin function 7 */
#define IOCON_PIO_FUNC9 0x09u         /*!<@brief Selects pin function 7 */
#define IOCON_PIO_FUNC11 0x0Bu
//bit 5:4
#define IOCON_PIO_MODE_INACT 	0x00u    /*!<@brief No addition pin function */
#define IOCON_PIO_MODE_PULLDOWN 0x10u    /*!<@brief Pull-down resistor enabled */
#define IOCON_PIO_MODE_PULLUP 	0x20u    /*!<@brief Pull-up resistor enabled */
#define IOCON_PIO_MODE_REPEATER 0x30u    /*!<@brief Repeater mode */
//bit 6
#define IOCON_PIO_SLEW_STANDARD 0x00u 	/*!<@brief Standard mode, output slew rate control is enabled */
#define IOCON_PIO_MODE_FAST  	0x40u   /*!<@brief Fast mode, output slew rate is faster. Refer to the appropriate specific device data sheet for details. */
//bit 7
#define IOCON_PIO_INV_DI 0x00u        	/*!<@brief Input function is not inverted */
#define IOCON_PIO_INV_EN 0x80u        	/*!<@brief Input function is inverted */
//bit 8
#define IOCON_PIO_DIGITAL_DI 0x00u  	/*!<@brief Disable digital function */
#define IOCON_PIO_DIGITAL_EN 0x0100u  	/*!<@brief Enables digital function */
//bit 9
#define IOCON_PIO_OPENDRAIN_DI 0x000u  	/*!<@brief Open drain is disabled */
#define IOCON_PIO_OPENDRAIN_EN 0x200u  	/*!<@brief Open drain is enable */
//bit 12 - FILTEROFF (only valid for non-I2C type-D pads)
#define IOCON_PIO_FILTER_ON     0x0000u   /*!<@brief Digital input filter ON (default) */
#define IOCON_PIO_FILTER_OFF    0x1000u   /*!<@brief Digital input filter OFF */
//bit 14 - EGP: only for I2C-tolerant pads (PIO0_13, PIO0_14, PIO1_20, PIO1_21)
#define IOCON_PIO_EGP_I2C       0x0000u   /*!<@brief EGP=0: I2C mode (default for I2C-tolerant pads) */
#define IOCON_PIO_EGP_GPIO      0x4000u   /*!<@brief EGP=1: GPIO/SPI mode for I2C-tolerant pads */
//bit 15 - I2CFILTER: only meaningful in I2C mode; safe to set to OFF for SPI use
